/**
 * Generates lib/images/manifest.generated.ts from everything under assets/content/.
 *
 * Content files are MDX and cannot `import`, but we still want next/image's
 * static dimensions and build-time optimization. So frontmatter carries a KEY
 * and zod validates it against this manifest — a typo fails the build instead
 * of rendering a broken image.
 *
 * Committed so tsc can see it; regenerated by `prebuild` and checked by
 * `content:check`, so it can never go stale in CI.
 */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const DIR = path.join(ROOT, 'assets/content');
const OUT = path.join(ROOT, 'lib/images/manifest.generated.ts');
const EXT = new Set(['.png', '.jpg', '.jpeg', '.webp', '.avif']);

function walk(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) return walk(full);
    return EXT.has(path.extname(e.name).toLowerCase()) ? [full] : [];
  });
}

/** 'assets/content/guides/foo/01-step.png' -> 'guides/foo/01-step' */
function keyFor(file: string): string {
  const rel = path.relative(DIR, file);
  return rel.slice(0, rel.length - path.extname(rel).length).split(path.sep).join('/');
}

function identFor(key: string, taken: Set<string>): string {
  let base = 'img_' + key.replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_|_$/g, '');
  let ident = base;
  let n = 2;
  while (taken.has(ident)) ident = `${base}_${n++}`;
  taken.add(ident);
  return ident;
}

const files = walk(DIR).sort();
const taken = new Set<string>();
const entries = files.map((f) => ({
  key: keyFor(f),
  ident: identFor(keyFor(f), taken),
  importPath: '@/' + path.relative(ROOT, f).split(path.sep).join('/'),
}));

const body = `// GENERATED by scripts/gen-image-manifest.ts — do not edit by hand.
// Run \`npm run assets:sync\` after adding or removing files in assets/content/.
import type { StaticImageData } from 'next/image';
${entries.map((e) => `import ${e.ident} from '${e.importPath}';`).join('\n')}

export const CONTENT_IMAGES = {
${entries.map((e) => `  '${e.key}': ${e.ident},`).join('\n')}
} satisfies Record<string, StaticImageData>;

export type ContentImageKey = keyof typeof CONTENT_IMAGES;

export const CONTENT_IMAGE_KEYS = Object.keys(CONTENT_IMAGES) as ContentImageKey[];
`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });
const prev = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
fs.writeFileSync(OUT, body);
console.log(
  `image manifest: ${entries.length} image(s)${prev === body ? ' (unchanged)' : ' (updated)'}`,
);
